const fs = require('fs');
const zlib = require('zlib');

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

let offset = 0;
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break;

  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const nameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const name = buf.toString('utf8', offset + 30, offset + 30 + nameLen);
  const dataStart = offset + 30 + nameLen + extraLen;

  if (name === 'word/document.xml') {
    const compressed = buf.slice(dataStart, dataStart + compSize);
    let content;
    if (compMethod === 8) {
      content = zlib.inflateRawSync(compressed).toString('utf8');
    } else {
      content = compressed.toString('utf8');
    }

    // Extract text with paragraph breaks
    // Split on <w:p to get paragraphs
    const paragraphs = content.split(/<w:p[ >]/).map(p => {
      // Get all <w:t> text
      const texts = [];
      const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
      let m;
      while ((m = re.exec(p)) !== null) {
        texts.push(m[1]);
      }
      return texts.join('');
    }).filter(p => p.length > 0);

    const fullText = paragraphs.join('\n');

    // Extract Maya Chen's section
    const lines = fullText.split('\n');
    let startIdx = -1;
    let endIdx = lines.length;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].includes('Maya Chen') && startIdx === -1) {
        startIdx = i;
      } else if (startIdx !== -1 && i > startIdx && lines[i].includes('Email:') && !lines[i].includes('maya.chen')) {
        endIdx = i - 1;
        break;
      }
    }
    console.log(lines.slice(startIdx, endIdx).join('\n'));
    break;
  }
  offset = dataStart + compSize;
}
