/**
 * Send Maya Chen's Customer Activity Report PDF via email.
 *
 * Prerequisites:
 *   npm install nodemailer
 *
 * Usage:
 *   Update the SMTP configuration below with your mail server details,
 *   then run:
 *     node send_report_email.js
 */

const nodemailer = require("nodemailer");
const path = require("path");

// ─── SMTP Configuration (update these with your mail server details) ────────
const SMTP_HOST = "smtp.company.com"; // e.g. "smtp.gmail.com"
const SMTP_PORT = 587; // 587 for TLS, 465 for SSL
const SMTP_SECURE = false; // true for port 465, false for 587
const SMTP_USER = "your.email@company.com";
const SMTP_PASS = "your-password-or-app-password";
// ────────────────────────────────────────────────────────────────────────────

// ─── Email Details ──────────────────────────────────────────────────────────
const FROM = SMTP_USER;
const TO = "ethan.it.specialist@company.com";
const SUBJECT = "Maya Chen — Customer Activity Report";
const BODY = `Hi Ethan,

Please find attached Maya Chen's Customer Activity Report for your review.

Summary:
  • Customer: Maya Chen (maya.chen@example.com)
  • Loyalty Tier: Gold
  • Total Orders: 7 (5 confirmed, 2 cancelled)

Let me know if you have any questions.

Best regards`;

const ATTACHMENT_PATH = path.join(__dirname, "Maya_Chen_Customer_Activity_Report.pdf");
// ────────────────────────────────────────────────────────────────────────────

async function main() {
  const transporter = nodemailer.createTransport({
    host: SMTP_HOST,
    port: SMTP_PORT,
    secure: SMTP_SECURE,
    auth: {
      user: SMTP_USER,
      pass: SMTP_PASS,
    },
  });

  const info = await transporter.sendMail({
    from: FROM,
    to: TO,
    subject: SUBJECT,
    text: BODY,
    attachments: [
      {
        filename: "Maya_Chen_Customer_Activity_Report.pdf",
        path: ATTACHMENT_PATH,
      },
    ],
  });

  console.log("Email sent successfully!");
  console.log("Message ID:", info.messageId);
}

main().catch((err) => {
  console.error("Failed to send email:", err.message);
  process.exit(1);
});
